m=list(re.finditer(r'Test input \(20x23\):\n(.*?)(?=\nWrong attempts used:)',t,re.S))[-1];g=[list(map(int,l.split())) for l in m.group(1).strip().splitlines()]
h,w=len(g),len(g[0]);seen=set();objs=[]
for r in range(h):
 for cc in range(w):
  col=g[r][cc]
  if col==3 or (r,cc) in seen:continue
  q=[(r,cc)];seen.add((r,cc));cells=[]
  for a,b in q:
   cells.append((a,b))
   for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:seen.add((x,y));q.append((x,y))
  r0=min(a for a,b in cells);c0=min(b for a,b in cells);shape=tuple(sorted((a-r0,b-c0) for a,b in cells));objs.append((col,len(cells),(r0,c0,max(a for a,b in cells),max(b for a,b in cells)),shape))
refs=[o for o in objs if o[0]==0]; print('L/reference objects:',[(x[1],tuple(v+1 for v in x[2])) for x in refs]);
for o in objs:
 peers=[q for q in objs if q is not o and q[3]==o[3]]
 if peers:print('matching components color,size,bbox1-based:',(o[0],o[1],tuple(v+1 for v in o[2])),'peers',[(q[0],q[1],tuple(v+1 for v in q[2])) for q in peers]);
print('ref bbox contains candidate extents?');rb=refs[0][2];
for o in objs:
 if o[3]==next(q[3] for q in objs if q[0]==6 and q[1]>10):print(o[0],tuple(v+1 for v in o[2]),'within ref bbox',rb[0]<=o[2][0] and o[2][2]<=rb[2] and rb[1]<=o[2][1] and o[2][3]<=rb[3])

